"""Frozen cross-language regression values generated by original IMFuRDE.m."""

import numpy as np
import pytest

from msentropy.core.imfrde import imfrde


SIGNAL = (
    np.sin(2 * np.pi * np.arange(513) / 37)
    + 0.1 * np.cos(2 * np.pi * np.arange(513) / 11)
    + 0.002 * np.arange(513)
)
CASES = (
    ((2, 6, 1, 5, 0, 1.3), [2.510030370101889, 2.7095293380777354, 2.880301109507764, 3.0056437865337924, 3.102447305567895]),
    ((2, 6, 1, 5, 1, 2.0), [-2.321814738712831, -2.328484868545784, -2.3377829363460587, -2.348851763048084, -2.3614073585298203]),
    ((3, 3, 2, 4, 0, 0.7), [2.551111633232201, 2.7480942353122653, 2.8467290811549124, 2.9292526281564233]),
    ((3, 3, 2, 4, 1, 1.3), [-7.924324990977147, -7.97129874113933, -8.01443841445852, -8.043582124189458]),
)


@pytest.mark.parametrize(("parameters", "expected"), CASES)
def test_imfrde_matches_original_matlab(parameters, expected):
    np.testing.assert_allclose(
        imfrde(SIGNAL, *parameters), expected, rtol=1e-11, atol=1e-11
    )


@pytest.mark.parametrize(
    "kwargs", [{"q": 1}, {"scale": 100}, {"tau": 0}, {"type_": 3}]
)
def test_imfrde_invalid_parameters_fail_closed(kwargs):
    defaults = dict(m=2, nc=6, tau=1, scale=5, type_=0, q=1.3)
    defaults.update(kwargs)
    with pytest.raises(ValueError):
        imfrde(np.arange(50, dtype=float), **defaults)


def test_imfrde_rejects_constant_signal():
    with pytest.raises(ValueError):
        imfrde(np.ones(200), 2, 6, 1, 5)
